{"title": "Cortex XDR audit - at a glance", "type": "vega", "aggs": [], "params": {"spec": "{
  "$schema": "https://vega.github.io/schema/vega/v5.json",
  "autosize": {
    "type": "fit",
    "contains": "padding"
  },
  "padding": 2,
  "data": [
    {
      "name": "s",
      "url": {
        "%context%": true,
        "index": "wazuh-alerts-*",
        "body": {
          "size": 0,
          "aggs": {
            "scoped": {
              "filter": {
                "bool": {
                  "filter": [
                    {
                      "term": {
                        "data.integration": "cortex_xdr"
                      }
                    }
                  ]
                }
              },
              "aggs": {
                "s": {
                  "filters": {
                    "filters": [
                      {
                        "match_all": {}
                      }
                    ]
                  },
                  "aggs": {
                    "am": {
                      "filter": {
                        "term": {
                          "data.cortex.event_type": "audit_management"
                        }
                      },
                      "aggs": {
                        "n": {
                          "cardinality": {
                            "field": "data.cortex.AUDIT_ID"
                          }
                        },
                        "admins": {
                          "cardinality": {
                            "field": "data.cortex.AUDIT_OWNER_NAME"
                          }
                        },
                        "fail": {
                          "filter": {
                            "prefix": {
                              "data.cortex.AUDIT_RESULT": "FAIL"
                            }
                          },
                          "aggs": {
                            "n": {
                              "cardinality": {
                                "field": "data.cortex.AUDIT_ID"
                              }
                            }
                          }
                        },
                        "keys": {
                          "filter": {
                            "term": {
                              "data.cortex.AUDIT_ENTITY": "API_KEY"
                            }
                          },
                          "aggs": {
                            "n": {
                              "cardinality": {
                                "field": "data.cortex.AUDIT_ID"
                              }
                            }
                          }
                        }
                      }
                    },
                    "ag": {
                      "filter": {
                        "bool": {
                          "filter": [
                            {
                              "term": {
                                "data.cortex.event_type": "audit_agent"
                              }
                            },
                            {
                              "term": {
                                "data.cortex.SUBTYPE": "Stop"
                              }
                            }
                          ]
                        }
                      },
                      "aggs": {
                        "eps": {
                          "cardinality": {
                            "field": "data.cortex.ENDPOINTNAME"
                          }
                        }
                      }
                    }
                  }
                }
              }
            }
          }
        },
        "%timefield%": "timestamp"
      },
      "format": {
        "property": "aggregations.scoped.s.buckets"
      }
    },
    {
      "name": "tiles",
      "values": [
        {
          "i": 0,
          "label": "Console actions",
          "bad": false
        },
        {
          "i": 1,
          "label": "Failed console actions",
          "bad": true
        },
        {
          "i": 2,
          "label": "API key changes",
          "bad": true
        },
        {
          "i": 3,
          "label": "Administrators",
          "bad": false
        },
        {
          "i": 4,
          "label": "Agent service stops",
          "bad": true
        },
        {
          "i": 5,
          "label": "Endpoints stopping agents",
          "bad": true
        }
      ],
      "transform": [
        {
          "type": "formula",
          "expr": "datum.i === 0 ? (length(data('s')) ? data('s')[0].am.n.value : 0) : datum.i === 1 ? (length(data('s')) ? data('s')[0].am.fail.n.value : 0) : datum.i === 2 ? (length(data('s')) ? data('s')[0].am.keys.n.value : 0) : datum.i === 3 ? (length(data('s')) ? data('s')[0].am.admins.value : 0) : datum.i === 4 ? (length(data('s')) ? data('s')[0].ag.doc_count : 0) : datum.i === 5 ? (length(data('s')) ? data('s')[0].ag.eps.value : 0) : 0",
          "as": "value"
        }
      ]
    }
  ],
  "marks": [
    {
      "type": "text",
      "from": {
        "data": "tiles"
      },
      "encode": {
        "update": {
          "x": {
            "signal": "(datum.i + 0.5) * width / 6"
          },
          "y": {
            "signal": "height * 0.46"
          },
          "align": {
            "value": "center"
          },
          "baseline": {
            "value": "middle"
          },
          "fontSize": {
            "signal": "max(14, min(height * 0.42, width / 6 * 0.26))"
          },
          "fontWeight": {
            "value": "bold"
          },
          "fill": {
            "signal": "datum.bad && datum.value > 0 ? '#BD271E' : '#343741'"
          },
          "text": {
            "signal": "format(datum.value, ',')"
          }
        }
      }
    },
    {
      "type": "text",
      "from": {
        "data": "tiles"
      },
      "encode": {
        "update": {
          "x": {
            "signal": "(datum.i + 0.5) * width / 6"
          },
          "y": {
            "signal": "height * 0.82"
          },
          "align": {
            "value": "center"
          },
          "baseline": {
            "value": "middle"
          },
          "fontSize": {
            "value": 12
          },
          "fill": {
            "value": "#69707D"
          },
          "text": {
            "field": "label"
          }
        }
      }
    }
  ]
}"}}

