{"title": "Cortex XDR audit - console source addresses", "type": "vega", "aggs": [], "params": {"spec": "{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "data": {
    "url": {
      "%context%": true,
      "index": "wazuh-alerts-*",
      "body": {
        "size": 0,
        "aggs": {
          "scoped": {
            "filter": {
              "bool": {
                "filter": [
                  {
                    "term": {
                      "data.integration": "cortex_xdr"
                    }
                  },
                  {
                    "term": {
                      "data.cortex.event_type": "audit_management"
                    }
                  }
                ]
              }
            },
            "aggs": {
              "b": {
                "terms": {
                  "field": "data.cortex.AUDIT_SOURCE_IP",
                  "size": 15
                },
                "aggs": {
                  "inner": {
                    "terms": {
                      "field": "data.cortex.AUDIT_RESULT",
                      "size": 5
                    },
                    "aggs": {
                      "n": {
                        "cardinality": {
                          "field": "data.cortex.AUDIT_ID"
                        }
                      }
                    }
                  }
                }
              }
            }
          }
        }
      },
      "%timefield%": "timestamp"
    },
    "format": {
      "property": "aggregations.scoped.b.buckets"
    }
  },
  "transform": [
    {
      "flatten": [
        "inner.buckets"
      ],
      "as": [
        "inner"
      ]
    },
    {
      "calculate": "datum.inner.n.value",
      "as": "n"
    },
    {
      "filter": "datum.n > 0"
    },
    {
      "calculate": "datum.key",
      "as": "y"
    },
    {
      "calculate": "indexof([\"SUCCESS\", \"FAIL\"], indexof(upper(datum.inner.key + ''), 'FAIL') === 0 ? 'FAIL' : datum.inner.key) >= 0 ? indexof(upper(datum.inner.key + ''), 'FAIL') === 0 ? 'FAIL' : datum.inner.key : 'other'",
      "as": "color"
    },
    {
      "aggregate": [
        {
          "op": "sum",
          "field": "n",
          "as": "n"
        }
      ],
      "groupby": [
        "y",
        "color"
      ]
    },
    {
      "joinaggregate": [
        {
          "op": "sum",
          "field": "n",
          "as": "total"
        }
      ],
      "groupby": [
        "y"
      ]
    },
    {
      "window": [
        {
          "op": "dense_rank",
          "as": "rank"
        }
      ],
      "sort": [
        {
          "field": "total",
          "order": "descending"
        },
        {
          "field": "y"
        }
      ]
    },
    {
      "filter": "datum.rank <= 15"
    },
    {
      "calculate": "({\"SUCCESS\": \"#54B399\", \"FAIL\": \"#E7664C\", \"other\": \"#98A2B3\"})[datum.color] || '#98A2B3'",
      "as": "color_hex"
    },
    {
      "calculate": "indexof([\"SUCCESS\", \"FAIL\", \"other\"], datum.color)",
      "as": "color_ord"
    },
    {
      "calculate": "(datum.color_ord < 10 ? '0' : '') + datum.color_ord + ' ' + datum.color",
      "as": "color_key"
    }
  ],
  "layer": [
    {
      "mark": {
        "type": "bar",
        "cornerRadiusEnd": 2,
        "height": {
          "band": 0.72
        }
      },
      "encoding": {
        "y": {
          "field": "y",
          "type": "nominal",
          "title": null,
          "sort": {
            "field": "total",
            "op": "max",
            "order": "descending"
          },
          "axis": {
            "labelLimit": 230,
            "labelFontSize": 10
          }
        },
        "x": {
          "field": "n",
          "type": "quantitative",
          "aggregate": "sum",
          "title": "Actions",
          "stack": "zero",
          "axis": {
            "tickMinStep": 1,
            "format": ",d"
          }
        },
        "color": {
          "field": "color_key",
          "type": "nominal",
          "title": "Result",
          "legend": {
            "orient": "right",
            "labelLimit": 180,
            "symbolType": "circle",
            "labelExpr": "slice(datum.label, 3)"
          },
          "scale": {
            "range": {
              "field": "color_hex"
            }
          }
        },
        "tooltip": [
          {
            "field": "y",
            "title": "Item"
          },
          {
            "field": "color",
            "title": "Split"
          },
          {
            "field": "n",
            "title": "Count"
          },
          {
            "field": "total",
            "title": "Total"
          }
        ]
      }
    },
    {
      "transform": [
        {
          "aggregate": [
            {
              "op": "sum",
              "field": "n",
              "as": "t"
            }
          ],
          "groupby": [
            "y",
            "total"
          ]
        }
      ],
      "mark": {
        "type": "text",
        "align": "left",
        "dx": 4,
        "fontSize": 10,
        "fill": "#69707D"
      },
      "encoding": {
        "y": {
          "field": "y",
          "type": "nominal",
          "sort": {
            "field": "total",
            "op": "max",
            "order": "descending"
          }
        },
        "x": {
          "field": "t",
          "type": "quantitative"
        },
        "text": {
          "field": "t",
          "type": "quantitative"
        }
      }
    }
  ],
  "config": {
    "view": {
      "stroke": null
    },
    "axis": {
      "grid": false
    }
  }
}"}}

